<script setup lang="ts">
useHead({ title: 'Организации — SARKISIAN CRM' });
import { BadgeRussianRuble, Building2, Plus, RefreshCw, Search, ShoppingBag, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const organizations = ref<any[]>([]);
const createOpen = ref(false);
const loading = ref(false);
const error = ref('');
const { actionBusy, runOperation } = useWorkspaceOperation(error);
const { selected, setEntity, closeEditor, markSaved, entityPanel, entityKeys } = useWorkspaceEntityDraft<any>(actionBusy);
const access = useWorkspaceAccess();
const canEdit = computed(() => access.can('customers.write'));
const pageLoaded = ref(false);
const search = ref('');
const status = ref('');
const notice = ref('');
const form = reactive({ name: '', legalName: '', inn: '', kpp: '', legalAddress: '', status: 'PROSPECT', discountTier: 0, creditLimit: 0 });
let searchTimer: ReturnType<typeof setTimeout>;
let loadVersion = 0;
const emptyForm = JSON.stringify(form);
const createDirty = computed(() => createOpen.value && JSON.stringify(form) !== emptyForm);
function closeCreate() { if (actionBusy.value || (createDirty.value && !window.confirm('Закрыть форму без сохранения организации?'))) return false; createOpen.value = false; Object.assign(form, JSON.parse(emptyForm)); return true; }
onBeforeRouteLeave(() => !actionBusy.value && (!createDirty.value || window.confirm('Есть несохранённая организация. Покинуть страницу?')));
const { panel: createPanel, keyboard: createKeys } = useCatalogDialog(computed(() => createOpen.value), closeCreate);
const headers = computed(() => ({ Authorization: `Bearer ${token.value}` }));
const statusLabels: Record<string, string> = { PROSPECT: 'Потенциальный клиент', ACTIVE: 'Активна', ON_HOLD: 'Приостановлена', ARCHIVED: 'В архиве' };
const memberLabels: Record<string, string> = { OWNER: 'Владелец', BUYER: 'Закупщик', ACCOUNTANT: 'Бухгалтер', EMPLOYEE: 'Сотрудник' };
const orderLabels: Record<string, string> = { NEW: 'Новый', CONFIRMED: 'Подтверждён', PAYMENT_WAITING: 'Ожидает оплату', PAID: 'Оплачен', ASSEMBLING: 'Собирается', SHIPPED: 'Отправлен', DELIVERED: 'Доставлен', CANCELLED: 'Отменён', REFUNDED: 'Возврат' };
const totals = computed(() => ({ active: organizations.value.filter(item => item.status === 'ACTIVE').length, people: organizations.value.reduce((sum, item) => sum + Number(item._count?.members || 0), 0), orders: organizations.value.reduce((sum, item) => sum + Number(item._count?.orders || 0), 0) }));

async function load() {
  const version = ++loadVersion;
  const identity = token.value;
  loading.value = true;
  error.value = '';
  try { const rows = await $fetch<any[]>('/customer-360/organizations', { baseURL: config.public.apiBase, headers: headers.value, query: { search: search.value || undefined, status: status.value || undefined } }); if (version !== loadVersion || token.value !== identity) return; organizations.value = rows; pageLoaded.value = true; }
  catch (reason:any) { if (version === loadVersion) error.value = typeof reason?.data?.message === 'string' ? reason.data.message : 'Не удалось загрузить организации. Повторите попытку.'; }
  finally { if (version === loadVersion) loading.value = false; }
}
async function openOrganization(item: any) { if (!closeEditor()) return; await runOperation(async () => setEntity(await $fetch(`/customer-360/organizations/${item.id}`, { baseURL: config.public.apiBase, headers: headers.value }))); }
async function createOrganization() {
  if (!canEdit.value) return;
  await runOperation(async () => {
  await $fetch('/customer-360/organizations', { baseURL: config.public.apiBase, method: 'POST', headers: headers.value, body: { ...form, legalName: form.legalName || undefined, inn: form.inn || undefined, kpp: form.kpp || undefined, legalAddress: form.legalAddress || undefined, discountTier: Number(form.discountTier), creditLimit: Number(form.creditLimit) } });
  Object.assign(form, { name: '', legalName: '', inn: '', kpp: '', legalAddress: '', status: 'PROSPECT', discountTier: 0, creditLimit: 0 });
  createOpen.value = false; notice.value = 'Организация создана'; await load(); setTimeout(() => notice.value = '', 2200);
  });
}
async function saveOrganization() {
  if (!selected.value || !canEdit.value) return;
  await runOperation(async () => {
  const saved = await $fetch<any>(`/customer-360/organizations/${selected.value.id}`, { baseURL: config.public.apiBase, method: 'PATCH', headers: headers.value, body: { name: selected.value.name, legalName: selected.value.legalName || undefined, inn: selected.value.inn || undefined, kpp: selected.value.kpp || undefined, legalAddress: selected.value.legalAddress || undefined, status: selected.value.status, discountTier: Number(selected.value.discountTier), creditLimit: Number(selected.value.creditLimit) } });
  markSaved(saved);
  notice.value = 'Организация сохранена'; await load(); setTimeout(() => notice.value = '', 2200);
  });
}
async function archiveOrganization(item:any){if (!canEdit.value) return; await runOperation(async () => {await $fetch(`/customer-360/organizations/${item.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:headers.value,body:{status:'ARCHIVED'}});notice.value='Организация перемещена в архив';await load();setTimeout(()=>notice.value='',2200)});}
async function moveOrganizationToTrash(item:any){if (!closeEditor()) return; await runOperation(async () => {await $fetch(`/data-lifecycle/ORGANIZATION/${item.id}/trash`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:{reason:'Удалено из реестра B2B-организаций'}});notice.value='Организация перемещена в корзину на 30 дней';await load();setTimeout(()=>notice.value='',2600)});}
function organizationMenu(event:MouseEvent,item:any){openContextMenu(event,item.name,[{label:'Открыть карточку',icon:'open',action:()=>openOrganization(item)},...(item.inn?[{label:'Копировать ИНН',icon:'copy' as const,action:()=>copyText(item.inn,'ИНН скопирован')}]:[]),...(item.status!=='ARCHIVED'?[{label:'Переместить в архив',icon:'archive' as const,danger:true,separator:true,confirm:`Переместить «${item.name}» в архив?`,action:()=>archiveOrganization(item)}]:[]),...(user.value?.role==='ADMIN'?[{label:'Переместить в корзину',icon:'trash' as const,danger:true,separator:item.status==='ARCHIVED',confirm:`Переместить «${item.name}» в корзину? Восстановить организацию можно в настройках экосистемы в течение 30 дней.`,action:()=>moveOrganizationToTrash(item)}]:[])],statusLabels[item.status])}
watch(search, () => { clearTimeout(searchTimer); searchTimer = setTimeout(load, 300); });
watch(status, load);
onBeforeUnmount(() => { ++loadVersion; clearTimeout(searchTimer); });
onMounted(load);
</script>

<template><main data-v-ui-62f6efe9efa8 class="org-page crm-standard">
  <header data-v-ui-62f6efe9efa8 class="page-header crm-page-header"><div data-v-ui-62f6efe9efa8><p data-v-ui-62f6efe9efa8>CRM / B2B</p><h1 data-v-ui-62f6efe9efa8>Организации</h1><span data-v-ui-62f6efe9efa8>Юридические лица, сотрудники, условия продаж и вся история работы</span></div><div data-v-ui-62f6efe9efa8><button data-v-ui-62f6efe9efa8 class="outline crm-button crm-button--refresh" @click="load"><RefreshCw data-v-ui-62f6efe9efa8 :size="16" :class="{spin:loading}" /> Обновить</button><button data-v-ui-62f6efe9efa8 class="primary crm-button crm-button--primary" :disabled="actionBusy || !canEdit" @click="createOpen=true"><Plus data-v-ui-62f6efe9efa8 :size="16" /> Новая организация</button></div></header>
  <p data-v-ui-62f6efe9efa8 v-if="error" class="operation-error" role="alert">{{ error }}</p>
  <WorkspaceLoading v-if="loading && !pageLoaded" label="Загружаем организации" />
  <div data-v-ui-62f6efe9efa8 v-else-if="pageLoaded" class="page-body">
    <section data-v-ui-62f6efe9efa8 class="kpis"><article class="crm-surface" data-v-ui-62f6efe9efa8><Building2 data-v-ui-62f6efe9efa8 :size="18" /><span data-v-ui-62f6efe9efa8>Организации</span><strong data-v-ui-62f6efe9efa8>{{ organizations.length }}</strong><small data-v-ui-62f6efe9efa8>в текущей выборке</small></article><article class="crm-surface" data-v-ui-62f6efe9efa8><BadgeRussianRuble data-v-ui-62f6efe9efa8 :size="18" /><span data-v-ui-62f6efe9efa8>Активные</span><strong data-v-ui-62f6efe9efa8>{{ totals.active }}</strong><small data-v-ui-62f6efe9efa8>с действующими условиями</small></article><article class="crm-surface" data-v-ui-62f6efe9efa8><Users data-v-ui-62f6efe9efa8 :size="18" /><span data-v-ui-62f6efe9efa8>Представители</span><strong data-v-ui-62f6efe9efa8>{{ totals.people }}</strong><small data-v-ui-62f6efe9efa8>связанных сотрудников</small></article><article class="crm-surface" data-v-ui-62f6efe9efa8><ShoppingBag data-v-ui-62f6efe9efa8 :size="18" /><span data-v-ui-62f6efe9efa8>Заказы B2B</span><strong data-v-ui-62f6efe9efa8>{{ totals.orders }}</strong><small data-v-ui-62f6efe9efa8>за всё время</small></article></section>
    <section data-v-ui-62f6efe9efa8 class="panel crm-surface"><div data-v-ui-62f6efe9efa8 class="filters crm-toolbar"><label class="crm-input-group" data-v-ui-62f6efe9efa8><Search data-v-ui-62f6efe9efa8 :size="16" /><input class="crm-input" data-v-ui-62f6efe9efa8 v-model="search" placeholder="Название, юридическое лицо или ИНН" /></label><select class="crm-input" data-v-ui-62f6efe9efa8 v-model="status"><option data-v-ui-62f6efe9efa8 value="">Все статусы</option><option data-v-ui-62f6efe9efa8 value="PROSPECT">Потенциальные</option><option data-v-ui-62f6efe9efa8 value="ACTIVE">Активные</option><option data-v-ui-62f6efe9efa8 value="ON_HOLD">Приостановленные</option><option data-v-ui-62f6efe9efa8 value="ARCHIVED">Архив</option></select></div><div data-v-ui-62f6efe9efa8 class="org-row head"><span data-v-ui-62f6efe9efa8>Организация</span><span data-v-ui-62f6efe9efa8>Реквизиты</span><span data-v-ui-62f6efe9efa8>Статус</span><span data-v-ui-62f6efe9efa8>Менеджер</span><span data-v-ui-62f6efe9efa8>Результаты</span></div><button data-v-ui-62f6efe9efa8 v-for="item in organizations" :key="item.id" class="org-row crm-button" @click="openOrganization(item)" @contextmenu.prevent="organizationMenu($event,item)"><span data-v-ui-62f6efe9efa8 class="identity"><i data-v-ui-62f6efe9efa8>{{ item.name.slice(0,1).toUpperCase() }}</i><span data-v-ui-62f6efe9efa8><strong data-v-ui-62f6efe9efa8>{{ item.name }}</strong><small data-v-ui-62f6efe9efa8>{{ item.legalName || 'Юридическое название не указано' }}</small></span></span><span data-v-ui-62f6efe9efa8 class="stack"><b data-v-ui-62f6efe9efa8>{{ item.inn ? `ИНН ${item.inn}` : 'ИНН не указан' }}</b><small data-v-ui-62f6efe9efa8>{{ item.kpp ? `КПП ${item.kpp}` : 'КПП не указан' }}</small></span><span data-v-ui-62f6efe9efa8><em data-v-ui-62f6efe9efa8 :class="`status-${item.status.toLowerCase()}`">{{ statusLabels[item.status] }}</em></span><span data-v-ui-62f6efe9efa8 class="stack"><b data-v-ui-62f6efe9efa8>{{ [item.accountManager?.firstName,item.accountManager?.lastName].filter(Boolean).join(' ') || 'Не назначен' }}</b><small data-v-ui-62f6efe9efa8>{{ item.accountManager?.email || 'Нужен ответственный' }}</small></span><span data-v-ui-62f6efe9efa8 class="stack"><b data-v-ui-62f6efe9efa8>{{ item._count.orders }} заказов</b><small data-v-ui-62f6efe9efa8>{{ item._count.members }} представителей · {{ item.discountTier }}% скидка</small></span></button><p data-v-ui-62f6efe9efa8 v-if="!organizations.length" class="empty">Организаций пока нет — добавьте первого B2B-клиента</p></section>
  </div>

  <aside data-v-ui-62f6efe9efa8 v-if="selected" class="backdrop admin-dialog-backdrop" @click.self="closeEditor"><div data-v-ui-62f6efe9efa8 ref="entityPanel" class="drawer admin-dialog admin-dialog--drawer" role="dialog" aria-modal="true" tabindex="-1" @keydown="entityKeys"><header data-v-ui-62f6efe9efa8><div data-v-ui-62f6efe9efa8><p data-v-ui-62f6efe9efa8>КАРТОЧКА B2B</p><h2 data-v-ui-62f6efe9efa8>{{ selected.name }}</h2><span data-v-ui-62f6efe9efa8>{{ selected.inn ? `ИНН ${selected.inn}` : 'Реквизиты заполняются' }}</span></div><button class="crm-button crm-button--icon" data-v-ui-62f6efe9efa8 @click="closeEditor" :disabled="actionBusy" aria-label="Закрыть карточку"><X data-v-ui-62f6efe9efa8 :size="19" /></button></header><div data-v-ui-62f6efe9efa8 class="drawer-body admin-dialog-body"><p data-v-ui-62f6efe9efa8 v-if="error" class="operation-error" role="alert">{{ error }}</p><fieldset data-v-ui-62f6efe9efa8 class="edit-grid ui-fieldset-reset" :disabled="actionBusy || !canEdit"><label data-v-ui-62f6efe9efa8>Название<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="selected.name" /></label><label data-v-ui-62f6efe9efa8>Юридическое название<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="selected.legalName" /></label><label data-v-ui-62f6efe9efa8>ИНН<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="selected.inn" /></label><label data-v-ui-62f6efe9efa8>КПП<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="selected.kpp" /></label><label data-v-ui-62f6efe9efa8>Статус<select class="crm-input" data-v-ui-62f6efe9efa8 v-model="selected.status"><option data-v-ui-62f6efe9efa8 value="PROSPECT">Потенциальный клиент</option><option data-v-ui-62f6efe9efa8 value="ACTIVE">Активна</option><option data-v-ui-62f6efe9efa8 value="ON_HOLD">Приостановлена</option><option data-v-ui-62f6efe9efa8 value="ARCHIVED">В архиве</option></select></label><label data-v-ui-62f6efe9efa8>Скидка, %<input class="crm-input" data-v-ui-62f6efe9efa8 v-model.number="selected.discountTier" type="number" min="0" max="100" /></label><label data-v-ui-62f6efe9efa8>Кредитный лимит, ₽<input class="crm-input" data-v-ui-62f6efe9efa8 v-model.number="selected.creditLimit" type="number" min="0" /></label><label data-v-ui-62f6efe9efa8 class="wide">Юридический адрес<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="selected.legalAddress" /></label><button class="crm-button crm-button--primary" data-v-ui-62f6efe9efa8 @click="saveOrganization" :disabled="actionBusy || !canEdit">Сохранить изменения</button></fieldset><section data-v-ui-62f6efe9efa8 class="details"><h3 data-v-ui-62f6efe9efa8><Users data-v-ui-62f6efe9efa8 :size="16" /> Представители</h3><div data-v-ui-62f6efe9efa8 v-for="member in selected.members" :key="member.id" class="detail-row"><span data-v-ui-62f6efe9efa8><strong data-v-ui-62f6efe9efa8>{{ [member.user.firstName,member.user.lastName].filter(Boolean).join(' ') || member.user.email }}</strong><small data-v-ui-62f6efe9efa8>{{ member.user.email }}</small></span><span data-v-ui-62f6efe9efa8><b data-v-ui-62f6efe9efa8>{{ memberLabels[member.role] }}</b><small data-v-ui-62f6efe9efa8>{{ member.jobTitle || (member.canSeeFinance ? 'Видит финансы' : 'Рабочий доступ') }}</small></span></div><p data-v-ui-62f6efe9efa8 v-if="!selected.members?.length" class="empty-small">Представители ещё не добавлены</p></section><section data-v-ui-62f6efe9efa8 class="details"><h3 data-v-ui-62f6efe9efa8><ShoppingBag data-v-ui-62f6efe9efa8 :size="16" /> Последние заказы</h3><div data-v-ui-62f6efe9efa8 v-for="order in selected.orders" :key="order.id" class="detail-row"><span data-v-ui-62f6efe9efa8><strong data-v-ui-62f6efe9efa8>{{ order.orderNumber }}</strong><small data-v-ui-62f6efe9efa8>{{ new Date(order.createdAt).toLocaleDateString('ru-RU') }}</small></span><span data-v-ui-62f6efe9efa8><b data-v-ui-62f6efe9efa8>{{ Number(order.finalAmount).toLocaleString('ru-RU') }} ₽</b><small data-v-ui-62f6efe9efa8>{{ orderLabels[order.status] || order.status }}</small></span></div><p data-v-ui-62f6efe9efa8 v-if="!selected.orders?.length" class="empty-small">Заказов пока нет</p></section></div></div></aside>
  <aside data-v-ui-62f6efe9efa8 v-if="createOpen" class="backdrop admin-dialog-backdrop" @click.self="closeCreate"><form data-v-ui-62f6efe9efa8 ref="createPanel" role="dialog" aria-modal="true" tabindex="-1" @keydown="createKeys" class="drawer create admin-dialog admin-dialog--drawer" @submit.prevent="createOrganization"><header data-v-ui-62f6efe9efa8><div data-v-ui-62f6efe9efa8><p data-v-ui-62f6efe9efa8>НОВЫЙ B2B-КЛИЕНТ</p><h2 data-v-ui-62f6efe9efa8>Организация</h2><span data-v-ui-62f6efe9efa8>Реквизиты и коммерческие условия</span></div><button class="crm-button crm-button--icon" data-v-ui-62f6efe9efa8 type="button" @click="closeCreate" :disabled="actionBusy" aria-label="Закрыть форму организации"><X data-v-ui-62f6efe9efa8 :size="19" /></button></header><div data-v-ui-62f6efe9efa8 class="drawer-body edit-grid admin-dialog-body"><p data-v-ui-62f6efe9efa8 v-if="error" class="operation-error" role="alert">{{ error }}</p><fieldset data-v-ui-62f6efe9efa8 class="ui-fieldset-reset ui-create-fields" :disabled="actionBusy || !canEdit"><label data-v-ui-62f6efe9efa8>Название<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="form.name" required /></label><label data-v-ui-62f6efe9efa8>Юридическое название<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="form.legalName" /></label><label data-v-ui-62f6efe9efa8>ИНН<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="form.inn" /></label><label data-v-ui-62f6efe9efa8>КПП<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="form.kpp" /></label><label data-v-ui-62f6efe9efa8>Начальный статус<select class="crm-input" data-v-ui-62f6efe9efa8 v-model="form.status"><option data-v-ui-62f6efe9efa8 value="PROSPECT">Потенциальный клиент</option><option data-v-ui-62f6efe9efa8 value="ACTIVE">Активна</option></select></label><label data-v-ui-62f6efe9efa8>Скидка, %<input class="crm-input" data-v-ui-62f6efe9efa8 v-model.number="form.discountTier" type="number" min="0" max="100" /></label><label data-v-ui-62f6efe9efa8>Кредитный лимит, ₽<input class="crm-input" data-v-ui-62f6efe9efa8 v-model.number="form.creditLimit" type="number" min="0" /></label><label data-v-ui-62f6efe9efa8 class="wide">Юридический адрес<input class="crm-input" data-v-ui-62f6efe9efa8 v-model="form.legalAddress" /></label><button class="crm-button" data-v-ui-62f6efe9efa8 type="submit">Создать организацию</button></fieldset></div></form></aside>
  <div data-v-ui-62f6efe9efa8 v-if="notice" class="toast">{{ notice }}</div>
</main></template>
